def transform(grid):
    out=[row[:] for row in grid]
    for color in (2,5):
        for comp in components(grid,color):
            for r,c in comp: out[r][c]=7
            rs=[p[0] for p in comp];cs=[p[1] for p in comp]
            t,l,b,r=min(rs),min(cs),max(rs),max(cs);h,w=b-t+1,r-l+1
            nh,nw=(2*h-1,2*w-1) if color==5 else ((h+1)//2,(w+1)//2)
            nt,nl=(t-h//2,l-w//2) if color==5 else (t+(h-nh)//2,l+(w-nw)//2)
            placed=[]
            for i in range(nh):
                si=(i*(h-1)+(nh-1)//2)//(nh-1) if nh>1 else 0
                for j in range(nw):
                    sj=(j*(w-1)+(nw-1)//2)//(nw-1) if nw>1 else 0
                    if (t+si,l+sj) in comp:
                        rr,cc=nt+i,nl+j
                        if 0<=rr<len(grid) and 0<=cc<len(grid[0]):out[rr][cc]=color;placed.append((rr,cc))
            if color==2 and not placed:out[t+(h-1)//2,l+(w-1)//2]=color
    return out
